use verus::prelude::*;

verus! {

    // A 64‐bit unsigned integer n is divisible by a 64‐bit unsigned factor f
    // if and only if n % f == 0.  We lift this to a spec on natural numbers.
    spec fn divides(factor: nat, candidate: nat) -> bool {
        candidate % factor == 0
    }

    // A natural number candidate > 1 is prime iff there is no f with
    // 1 < f < candidate that divides candidate.
    spec fn is_prime(candidate: nat) -> bool {
        candidate > 1 &&
        forall |f: nat|  1 < f && f < candidate
                       ==> !divides(f, candidate)
    }

    // A concrete u64 primality test by trial division from 2..candidate−1
    fn test_prime(candidate: u64) -> (result: bool)
        requires
            // We only handle strictly greater than 1
            candidate > 1
        ensures
            // The result must exactly match the spec‐level is_prime
            result == is_prime(candidate as nat)
    {
        let mut f: u64 = 2;
        // Try every f from 2 up to candidate−1
        while f < candidate {
            // f stays in [2, candidate]
            invariant 2 <= f && f <= candidate;
            // We've already checked all divisors i in [2, f), and found none.
            invariant forall |i: u64|  2 <= i && i < f
                               ==> candidate % i != 0;
            // f increases, so candidate − f decreases
            decreases candidate - f;

            if candidate % f == 0 {
                // Found a non‐trivial divisor → not prime
                return false;
            }
            f = f + 1;
        }

        // No divisor found ⇒ prime
        true
    }

}